 void snapshot(String name)throws Exception{JSONObject o=new JSONObject();o.put("name",name);o.put("layout",c.layout());o.put("main",m.editorText());o.put("addingHole",m.editorField("addingHole"));o.put("key",g.key());o.put("selected",m.call(m.vertexState(),"selected",new Class[]{}));o.put("present",c.present());JSONArray texts=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),texts);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",texts);m.capture("mvisual-map-hole-"+name);v.emit("MAP_HOLE_VISUAL "+o.toString());if(c.present())v.buttonsReachable("Удалить");for(int i=0;i<texts.length();i++){JSONObject t=texts.getJSONObject(i);if(t.getBoolean("visible"))m.check(t.getBoolean("arimo"),"Arimo on polygon map confirmation/control "+t.getString("text"));}}
